type Database = Awaited<ReturnType<typeof openDurableDatabase>>;
type ImportPage = {
  jobId: string;
  references: ProfileReferenceInput[];
  cursor: string | null;
  isComplete: boolean;
  total?: number;
  remoteId?: string;
  title?: string;
  collection?: ProfileCollectionProgress;
  shouldPruneUnseen?: boolean;
};
const MAX_FAILURE_MESSAGE_LENGTH = 2000;
const INITIAL_RETRY_MS = 60_000;
const MAX_BACKOFF_MS = 15 * 60_000;
const MIN_RETRY_MS = 1000;
const MAX_BACKOFF_EXPONENT = 4;
const MAX_DATE_MS = 8_640_000_000_000_000;

const identity = (...parts: string[]): string =>
  createHash('sha256').update(JSON.stringify(parts)).digest('hex');

type UnfinishedImportStep = Extract<
  ProfileImportStep,
  'enumerate' | 'download' | 'analysis'
>;

export class UnfinishedImport extends Error {
  constructor(
    readonly step: UnfinishedImportStep,
    readonly reasonCode: FailureReasonCode,
  ) {
    super('Import has unfinished references');
    this.name = 'UnfinishedImport';
  }
}

const guidanceDocument = (document: {
  id: string;
  title: string;
  markdown: string;
  attachments?: GuidanceDocument['attachments'] | null;
  references?: GuidanceDocument['references'] | null;
  origin?: GuidanceDocument['origin'] | null;
}): GuidanceDocument =>
  GuidanceDocumentSchema.parse({
    id: document.id,
    title: document.title,
    markdown: document.markdown,
    ...(document.attachments?.length
      ? { attachments: document.attachments }
      : {}),
    ...(document.references ? { references: document.references } : {}),
    ...(document.origin ? { origin: document.origin } : {}),
  });

const savedGuidance = (
  record: typeof guidance.$inferSelect & {
    origin?: SavedGuidance['origin'] | null;
    sync?: SavedGuidance['sync'] | null;
    syncMode?: SavedGuidance['syncMode'] | null;
  },
): SavedGuidance => {
  const document = guidanceDocument(record);
  const verifier = record.verifier
    ? GuidanceVerifierSchema.parse(record.verifier)
    : undefined;
  return SavedGuidanceSchema.parse({
    ...document,
    isEnabled: record.isEnabled,
    ...(record.sync ? { sync: record.sync } : {}),
    ...(record.sync && record.syncMode ? { syncMode: record.syncMode } : {}),
    ...(verifier
      ? {
          verifier: {
            isStale: verifier.sourceDigest !== guidanceSourceDigest(document),
          },
        }
      : {}),
  });
};

export class ProfileRecords {
  private isClosed = false;
  readonly plans: ProfilePlans;
  private readonly guidanceSources: GuidanceSources;
  private constructor(
    readonly directory: string,
    private readonly db: Database,
  ) {
    this.plans = new ProfilePlans(db);
    this.guidanceSources = new GuidanceSources(db);
  }

  static openReadOnly({
    root,
    accountId,
  }: {
    root: string;
    accountId: string;
  }): ProfileRecords | null {
    if (!accountId.trim())
      throw new Error('A signed-in account is required for profiles');
    const directory = ProfileRecords.directoryFor({ root, accountId });
    const database = openReadOnlyDatabase({
      databasePath: path.join(directory, 'profile.sqlite'),
      schemaVersion: PROFILE_SCHEMA_VERSION,
    });
    return database ? new ProfileRecords(directory, database) : null;
  }

  static async open({
    root,
    accountId,
  }: {
    root: string;
    accountId: string;
  }): Promise<ProfileRecords> {
    if (!accountId.trim())
      throw new Error('A signed-in account is required for profiles');
    const directory = ProfileRecords.directoryFor({ root, accountId });
    const db = await openDurableDatabase({
      databasePath: path.join(directory, 'profile.sqlite'),
      schema: PROFILE_SCHEMA,
      migrations: PROFILE_MIGRATIONS,
    });
    db.insert(profile)
      .values({ singleton: 1, id: randomUUID(), isEnabled: false, revision: 1 })
      .onConflictDoNothing()
      .run();
    const records = new ProfileRecords(directory, db);
    records.plans.initializeOnboarding();
    records.plans.backfillApprovedCollections();
    return records;
  }

  static directoryFor({
    root,
    accountId,
  }: {
    root: string;
    accountId: string;
  }): string {
    if (!accountId.trim())
      throw new Error('A signed-in account is required for profiles');
    return path.join(root, 'profiles', identity(accountId));
  }

  profile() {
    const record = this.db.select().from(profile).get();
    if (!record) throw new Error('Profile metadata is missing');
    return record;
  }

  setEnabled(isEnabled: boolean): void {
    this.db.update(profile).set({ isEnabled }).run();
  }

  updateSettings(input: ProfileSettings): void {
    transaction(this.db, () => {
      this.db
        .update(profile)
        .set({
          ...(input.isEnabled !== undefined
            ? { isEnabled: input.isEnabled }
            : {}),
          ...(input.autonomousReferences !== undefined
            ? { autonomousReferences: input.autonomousReferences }
            : {}),
        })
        .run();
      if (input.isEnabled) this.queueIndex(input.runtime);
    });
  }

  setAutonomousReferences(isOn: boolean): void {
    this.db.update(profile).set({ autonomousReferences: isOn }).run();
  }

  referenceAutonomy(): ReferenceAutonomy {
    const { isEnabled, autonomousReferences } = this.profile();
    return isEnabled && autonomousReferences ? 'on' : 'off';
  }

  listGuidance(): SavedGuidance[] {
    return this.db
      .select({
        ...getTableColumns(guidance),
        origin: guidanceSources.origin,
        sync: guidanceSources.sync,
        syncMode: guidanceSources.syncMode,
      })
      .from(guidance)
      .leftJoin(guidanceSources, eq(guidanceSources.id, guidance.id))
      .orderBy(guidance.id)
      .all()
      .map(savedGuidance);
  }

  getGuidance(id: string): SavedGuidance {
    return savedGuidance(this.guidanceRecord(id));
  }

  private guidanceRecord(id: string) {
    const document = this.db
      .select({
        ...getTableColumns(guidance),
        origin: guidanceSources.origin,
        sync: guidanceSources.sync,
        syncMode: guidanceSources.syncMode,
      })
      .from(guidance)
      .leftJoin(guidanceSources, eq(guidanceSources.id, guidance.id))
      .where(eq(guidance.id, id))
      .get();
    if (!document)
      throw new GuidanceError('guidance_not_found', 'Unknown saved guidance');
    return document;
  }

  getGuidanceVerifier(id: string) {
    const stored = this.guidanceRecord(id);
    const source = guidanceDocument(stored);
    const sourceDigest = guidanceSourceDigest(source);
    const verifier = stored.verifier
      ? GuidanceVerifierSchema.parse(stored.verifier)
      : undefined;
    return { source, sourceDigest, ...(verifier ? { verifier } : {}) };
  }

  addGuidance(input: GuidanceInput): SavedGuidance {
    const { origin, sync, ...document } = {
      ...GuidanceInputSchema.parse(input),
      id: randomUUID(),
    };
    return transaction(this.db, () => {
      this.db.insert(guidance).values(document).run();
      this.guidanceSources.set({ id: document.id, origin, sync });
      return this.getGuidance(document.id);
    });
  }

  updateGuidance({
    id,
    ...input
  }: GuidanceUpdate & { id: string }): SavedGuidance {
    const { origin, sync, ...update } = GuidanceUpdateSchema.parse(input);
    return transaction(this.db, () => {
      const source = this.guidanceRecord(id);
      if (
        update.verifier &&
        update.verifier.sourceDigest !==
          guidanceSourceDigest(guidanceDocument(source))
      )
        throw new GuidanceError(
          'guidance_source_changed',
          'Saved context changed while the verifier was authored. Retrieve it again and revise the verifier before saving.',
        );
      if (
        update.verifier &&
        update.verifier.package === undefined &&
        source.verifier
      ) {
        const savedVerifier = GuidanceVerifierSchema.parse(source.verifier);
        if (savedVerifier.package) {
          if (savedVerifier.sourceDigest !== update.verifier.sourceDigest)
            throw new GuidanceError(
              'guidance_source_changed',
              'The saved executable package belongs to different source content. Supply a revised --verifier-package or remove the saved verifier before saving a Markdown-only recipe.',
            );
          update.verifier = {
            ...update.verifier,
            package: savedVerifier.package,
          };
        }
      }
      if (Object.keys(update).length)
        this.db.update(guidance).set(update).where(eq(guidance.id, id)).run();
      this.guidanceSources.set({ id, origin, sync });
      return this.getGuidance(id);
    });
  }

  setGuidanceSyncMode({
    id,
    syncMode,
  }: {
    id: string;
    syncMode: SourceSyncMode;
  }): SavedGuidance {
    const updated = this.db
      .update(guidanceSources)
      .set({ syncMode: SourceSyncModeSchema.parse(syncMode) })
      .where(eq(guidanceSources.id, id))
      .returning({ id: guidanceSources.id })
      .all();
    if (!updated.length)
      throw new GuidanceError(
        'guidance_not_found',
        'Connect a source before choosing how this document syncs',
      );
    return this.getGuidance(id);
  }

  setSourceSyncMode({
    id,
    syncMode,
  }: {
    id: string;
    syncMode: SourceSyncMode;
  }): void {
    this.source(id);
    this.db
      .update(sources)
      .set({ syncMode: SourceSyncModeSchema.parse(syncMode) })
      .where(eq(sources.id, id))
      .run();
  }

  removeGuidance(id: string): void {
    transaction(this.db, () => {
      this.getGuidance(id);
      this.db.delete(guidance).where(eq(guidance.id, id)).run();
    });
  }

  resolveGuidance(input: GuidanceSelection): GuidanceDocument[] {
    const selection = GuidanceSelectionSchema.parse(input);
    if (selection.mode === 'off') return [];
    const documents = this.db
      .select({
        id: guidance.id,
        title: guidance.title,
        markdown: guidance.markdown,
        attachments: guidance.attachments,
        references: guidance.references,
        isEnabled: guidance.isEnabled,
        origin: guidanceSources.origin,
      })
      .from(guidance)
      .leftJoin(guidanceSources, eq(guidanceSources.id, guidance.id))
      .orderBy(guidance.id)
      .all();
    if (
      selection.excludedIds.some(
        (id) => !documents.some((document) => document.id === id),
      )
    )
      throw new GuidanceError(
        'guidance_not_found',
        'Unknown saved guidance exclusion',
      );
    const selected = documents
      .filter(
        (document) =>
          document.isEnabled && !selection.excludedIds.includes(document.id),
      )
      .map(guidanceDocument);
    return selected;
  }

  sources() {
    return this.db
      .select()
      .from(sources)
      .where(isNull(sources.removedAt))
      .orderBy(sources.id)
      .all();
  }

  addSource(input: ProfileSourceInput) {
    const value = ProfileSourceInputSchema.parse(input);
    const id = identity(value.provider, value.remoteId);
    const isRemoved = Boolean(
      this.db.select().from(sources).where(eq(sources.id, id)).get()?.removedAt,
    );
    this.db
      .insert(sources)
      .values({ ...value, id, isIncluded: true })
      .onConflictDoUpdate({
        target: sources.id,
        set: {
          title: value.title,
          url: value.url ?? null,
          removedAt: null,
          ...(isRemoved ? { syncMode: 'daily' as const } : {}),
        },
      })
      .run();
    return this.source(id);
  }

  source(id: string) {
    const source = this.db
      .select()
      .from(sources)
      .where(and(eq(sources.id, id), isNull(sources.removedAt)))
      .get();
    if (!source) throw new Error('Unknown profile source');
    return source;
  }

  setSourceIncluded({
    sourceId,
    isIncluded,
  }: {
    sourceId: string;
    isIncluded: boolean;
  }): void {
    this.source(sourceId);
    transaction(this.db, () => {
      this.db
        .update(sources)
        .set({ isIncluded })
        .where(eq(sources.id, sourceId))
        .run();
      this.bump();
    });
  }

  removeSource(sourceId: string): void {
    this.source(sourceId);
    transaction(this.db, () => {
      const affected = this.references(sourceId);
      this.db
        .update(sources)
        .set({ removedAt: new Date().toISOString() })
        .where(eq(sources.id, sourceId))
        .run();
      this.db
        .update(importJobs)
        .set({ state: 'paused' })
        .where(eq(importJobs.sourceId, sourceId))
        .run();
      this.db
        .delete(memberships)
        .where(eq(memberships.sourceId, sourceId))
        .run();
      affected.forEach((reference) => this.queueOrphan(reference));
      this.bump();
    });
  }

  removeReference(referenceId: string): void {
    transaction(this.db, () => {
      const reference = this.libraryReferences([referenceId]).find(
        (item) => item.id === referenceId,
      );
      if (!reference) throw new Error('Unknown saved reference');
      const activeImport = this.db
        .select({ id: importJobs.id })
        .from(importJobs)
        .where(
          and(
            inArray(importJobs.sourceId, reference.sourceIds),
            inArray(importJobs.state, ['pending', 'paused', 'failed']),
          ),
        )
        .get();
      if (activeImport)
        throw new Error(
          'This reference belongs to an unfinished import. Finish the import before removing the reference.',
        );
      this.db
        .delete(memberships)
        .where(eq(memberships.referenceId, referenceId))
        .run();
      this.queue(reference, 'delete');
      this.bump();
    });
  }

  saveLocalReferences(input: {
    source: ProfileSourceInput;
    references: ProfileReferenceInput[];
  }) {
    return transaction(this.db, () => {
      const source = this.addSource(input.source);
      const references = input.references.map((reference) =>
        this.writeReference(source.id, reference),
      );
      this.bump();
      return { source, references };
    });
  }

  saveReference({
    sourceId,
    reference,
  }: {
    sourceId: string;
    reference: ProfileReferenceInput;
  }): ProfileReference {
    return transaction(this.db, () => this.writeReference(sourceId, reference));
  }

  references(sourceId?: string): ProfileReference[] {
    const ids = this.db
      .select({ id: memberships.referenceId })
      .from(memberships)
      .where(sourceId ? eq(memberships.sourceId, sourceId) : undefined);
    return this.db
      .select()
      .from(references)
      .where(inArray(references.id, ids))
      .orderBy(references.id)
      .all()
      .map(({ id, revision, body }) => ({ ...body, id, revision }));
  }

  libraryReferences(referencePrefixes?: string[]): DesignLibraryReference[] {
    if (referencePrefixes?.length === 0) return [];
    const rows = this.db
      .select({
        reference: references,
        sourceId: sources.id,
        observation: observations.body,
      })
      .from(references)
      .innerJoin(memberships, eq(memberships.referenceId, references.id))
      .innerJoin(sources, eq(sources.id, memberships.sourceId))
      .leftJoin(
        observations,
        and(
          eq(observations.referenceId, references.id),
          eq(observations.revision, references.revision),
        ),
      )
      .where(
        and(
          isNull(sources.removedAt),
          referencePrefixes
            ? or(
                ...referencePrefixes.map((prefix) =>
                  and(
                    gte(references.id, prefix),
                    lt(references.id, `${prefix}g`),
                  ),
                ),
              )
            : undefined,
        ),
      )
      .orderBy(references.id, sources.id)
      .all();
    const entries = new Map<string, DesignLibraryReference>();
    for (const { reference, sourceId, observation } of rows) {
      const existing = entries.get(reference.id);
      if (existing) existing.sourceIds.push(sourceId);
      else
        entries.set(reference.id, {
          ...reference.body,
          id: reference.id,
          revision: reference.revision,
          sourceIds: [sourceId],
          observation,
        });
    }
    return [...entries.values()];
  }

  reference(id: string): ProfileReference | null {
    const row = this.db
      .select()
      .from(references)
      .where(eq(references.id, id))
      .get();
    return row ? { ...row.body, id: row.id, revision: row.revision } : null;
  }

  saveObservation(input: ProfileObservation): void {
    const value = ProfileObservationSchema.parse(input);
    transaction(this.db, () => {
      const reference = this.reference(value.referenceId);
      if (!reference || reference.revision !== value.revision)
        throw new Error('Observation revision is no longer current');
      this.db
        .insert(observations)
        .values({
          referenceId: value.referenceId,
          revision: value.revision,
          body: value,
        })
        .onConflictDoUpdate({
          target: observations.referenceId,
          set: { revision: value.revision, body: value },
        })
        .run();
      this.queue(reference, 'upsert');
      this.bump();
    });
  }

  observation(referenceId: string): ProfileObservation | null {
    const row = this.db
      .select()
      .from(observations)
      .where(eq(observations.referenceId, referenceId))
      .get();
    return row?.revision === this.reference(referenceId)?.revision
      ? (row?.body ?? null)
      : null;
  }

  candidates(
    hits: Array<{ referenceId: string; revision: number }>,
  ): ProfileCandidate[] {
    return hits.flatMap(({ referenceId, revision }) => {
      const reference = this.reference(referenceId);
      const observation = this.observation(referenceId);
      const eligible = this.db
        .select({ source: sources })
        .from(memberships)
        .innerJoin(sources, eq(sources.id, memberships.sourceId))
        .where(
          and(
            eq(memberships.referenceId, referenceId),
            eq(sources.isIncluded, true),
            isNull(sources.removedAt),
          ),
        )
        .all();
      if (
        !reference ||
        !observation ||
        observation.evidence === 'provisional' ||
        reference.revision !== revision ||
        !eligible.length
      )
        return [];
      return [
        {
          reference,
          observation,
          sources: eligible.map(({ source }) => ({
            ...source,
            url: source.url ?? undefined,
          })),
        },
      ];
    });
  }

  pendingIndex(limit = 100): ProfileIndexWork[] {
    return this.db
      .select()
      .from(indexWork)
      .where(eq(indexWork.state, 'pending'))
      .orderBy(indexWork.referenceId)
      .limit(limit)
      .all();
  }

  coverage(sourceId?: string) {
    return this.referenceCoverage(
      this.references(sourceId),
      sourceId !== undefined,
    );
  }

  importCoverage(jobId: string) {
    const ids = this.db
      .select({ id: memberships.referenceId })
      .from(memberships)
      .where(eq(memberships.seenJobId, jobId));
    const items = this.db
      .select()
      .from(references)
      .where(inArray(references.id, ids))
      .all()
      .map(({ id, revision, body }) => ({ ...body, id, revision }));
    return this.referenceCoverage(items, true, jobId);
  }

  private referenceCoverage(
    items: ProfileReference[],
    isScoped: boolean,
    jobId?: string,
  ) {
    const receipts = new Map(
      this.db
        .select()
        .from(indexWork)
        .all()
        .map((work) => [work.referenceId, work]),
    );
    return {
      references: items.length,
      downloaded: items.filter(
        (item) =>
          item.media.length > 0 &&
          item.media.length >= (item.remoteImages?.length ?? 0),
      ).length,
      unsupported: items.filter((item) => item.unsupportedReason).length,
      failed: new Set(
        this.failures(jobId)
          .filter((failure) =>
            items.some((item) => item.id === failure.referenceId),
          )
          .map((failure) => failure.referenceId),
      ).size,
      analyzed: items.filter((item) =>
        hasCompletedAnalysis(this.observation(item.id)),
      ).length,
      provisional: items.filter(
        (item) => this.observation(item.id)?.evidence === 'provisional',
      ).length,
      indexed: items.filter((item) => {
        const work = receipts.get(item.id);
        return (
          work?.state === 'indexed' &&
          work.operation === 'upsert' &&
          work.revision === item.revision &&
          this.observation(item.id)
        );
      }).length,
      pendingIndex: isScoped
        ? items.filter((item) => receipts.get(item.id)?.state === 'pending')
            .length
        : [...receipts.values()].filter((item) => item.state === 'pending')
            .length,
    };
  }

  reindex(runtime: ProfileRuntime): { upserts: number; deletions: number } {
    return transaction(this.db, () => {
      const activeIds = new Set(this.references().map((item) => item.id));
      const work = new Map(
        this.db
          .select()
          .from(indexWork)
          .all()
          .map((item) => [item.referenceId, item]),
      );
      let upserts = 0;
      let deletions = 0;
      for (const row of this.db.select().from(references).all()) {
        const reference = { ...row.body, id: row.id, revision: row.revision };
        const operation =
          activeIds.has(row.id) && this.observation(row.id)
            ? 'upsert'
            : 'delete';
        if (operation === 'upsert') upserts += 1;
        else deletions += 1;
        const pending = work.get(row.id);
        if (
          pending?.state === 'pending' &&
          pending.operation === operation &&
          pending.revision === row.revision
        )
          continue;
        this.queue(reference, operation);
      }
      this.queueIndex(runtime);
      return { upserts, deletions };
    });
  }

  rebuild() {
    return this.db.select().from(indexRebuild).get() ?? null;
  }

  queueIndex(runtime: ProfileRuntime): void {
    const job = { id: randomUUID(), runtime };
    this.db
      .insert(indexRebuild)
      .values({ singleton: 1, ...job })
      .onConflictDoUpdate({ target: indexRebuild.singleton, set: job })
      .run();
  }

  completeRebuild(id: string): void {
    this.db.delete(indexRebuild).where(eq(indexRebuild.id, id)).run();
  }

  acknowledgeIndex(
    work: ProfileIndexWork & { engineId: string | null },
  ): boolean {
    return transaction(this.db, () => {
      const current = this.db
        .select()
        .from(indexWork)
        .where(
          and(
            eq(indexWork.referenceId, work.referenceId),
            eq(indexWork.id, work.id),
          ),
        )
        .get();
      if (
        !current ||
        current.revision !== work.revision ||
        current.operation !== work.operation
      )
        return false;
      if (work.operation === 'delete')
        this.db.delete(indexWork).where(eq(indexWork.id, work.id)).run();
      else
        this.db
          .update(indexWork)
          .set({ state: 'indexed', engineId: work.engineId })
          .where(eq(indexWork.id, work.id))
          .run();
      return true;
    });
  }

  saveLocalImport(input: {
    source: ProfileSourceInput;
    reference: ProfileReferenceInput;
    runtime: ProfileRuntime;
  }) {
    if (
      input.source.provider !== input.reference.provider ||
      input.source.remoteId !== input.reference.remoteId
    )
      throw new Error('Local reference identity must match its source');
    return transaction(this.db, () => {
      const source = this.addSource(input.source);
      const job = this.writeImport({
        sourceId: source.id,
        runtime: input.runtime,
      });
      this.writeReference(source.id, input.reference, job.id);
      this.db
        .update(importJobs)
        .set({ isEnumerated: true, enumerated: 1, total: 1 })
        .where(eq(importJobs.id, job.id))
        .run();
      const savedJob = this.jobs().find((item) => item.id === job.id);
      if (!savedJob) throw new Error('Saved profile import is missing');
      return { source, job: savedJob };
    });
  }

  startImport({
    sourceId,
    runtime,
  }: {
    sourceId: string;
    runtime: ProfileRuntime;
  }) {
    this.source(sourceId);
    const existing = this.jobs().find(
      (job) => job.sourceId === sourceId && job.state === 'pending',
    );
    if (existing) return existing;
    return transaction(this.db, () => this.writeImport({ sourceId, runtime }));
  }

  private writeImport({
    sourceId,
    runtime,
  }: {
    sourceId: string;
    runtime: ProfileRuntime;
  }) {
    const id = randomUUID();
    this.db
      .update(importJobs)
      .set({ state: 'superseded' })
      .where(
        and(
          eq(importJobs.sourceId, sourceId),
          ne(importJobs.state, 'complete'),
        ),
      )
      .run();
    this.db
      .insert(importJobs)
      .values({
        id,
        sourceId,
        runtime,
        state: 'pending',
        enumerated: 0,
        updatedAt: new Date().toISOString(),
      })
      .run();
    const job = this.jobs().find((item) => item.id === id);
    if (!job) throw new Error('Started profile import is missing');
    return job;
  }

  jobs() {
    const cooldowns = this.db.select().from(providerCooldowns).all();
    const providers = new Map(
      this.db
        .select()
        .from(sources)
        .all()
        .map((source) => [source.id, source.provider]),
    );
    return this.db
      .select()
      .from(importJobs)
      .orderBy(importJobs.updatedAt, importJobs.id)
      .all()
      .map((job) => ({
        ...job,
        retryAt:
          cooldowns.find(
            (cooldown) =>
              job.state === 'pending' &&
              cooldown.provider === providers.get(job.sourceId) &&
              Date.parse(cooldown.retryAt) > Date.now(),
          )?.retryAt ?? null,
      }));
  }

  deferImport({ id, retryAfterMs }: { id: string; retryAfterMs?: number }) {
    const job = this.jobs().find((item) => item.id === id);
    if (!job) throw new Error('Unknown profile import');
    const source = this.db
      .select()
      .from(sources)
      .where(eq(sources.id, job.sourceId))
      .get();
    if (!source) throw new Error('Profile import source is missing');
    if (!isRemoteProfileProvider(source.provider))
      throw new Error('Only connected providers support rate-limit deferral');
    const previous = this.db
      .select()
      .from(providerCooldowns)
      .where(eq(providerCooldowns.provider, source.provider))
      .get();
    const now = Date.now();
    const isRecent =
      previous && Date.parse(previous.retryAt) >= now - MAX_BACKOFF_MS;
    const attempts = isRecent
      ? Math.min(previous.attempts + 1, MAX_BACKOFF_EXPONENT + 1)
      : 1;
    const backoff = Math.min(
      MAX_BACKOFF_MS,
      INITIAL_RETRY_MS * 2 ** (attempts - 1),
    );
    const guidance =
      retryAfterMs !== undefined &&
      Number.isFinite(retryAfterMs) &&
      retryAfterMs >= 0 &&
      retryAfterMs <= MAX_DATE_MS - now
        ? retryAfterMs
        : backoff;
    const retryAt = new Date(
      Math.max(
        previous ? Date.parse(previous.retryAt) : now,
        now + Math.max(MIN_RETRY_MS, guidance),
      ),
    ).toISOString();
    return transaction(this.db, () => {
      const cooldown = { provider: source.provider, retryAt, attempts };
      this.db
        .insert(providerCooldowns)
        .values(cooldown)
        .onConflictDoUpdate({
          target: providerCooldowns.provider,
          set: cooldown,
        })
        .run();
      this.db
        .update(importJobs)
        .set({
          error:
            'Waiting for the provider rate limit; retry is scheduled automatically',
          updatedAt: new Date(now).toISOString(),
        })
        .where(and(eq(importJobs.id, id), eq(importJobs.state, 'pending')))
        .run();
      return cooldown;
    });
  }

  updateJob({
    id,
    state,
    error = null,
  }: {
    id: string;
    state: 'pending' | 'paused' | 'failed' | 'complete';
    error?: string | null;
  }): void {
    const job = this.jobs().find((item) => item.id === id);
    if (!job || job.state === 'superseded')
      throw new Error('Import job is no longer active');
    if (state === 'complete') {
      if (job.state !== 'pending')
        throw new Error('Import has unfinished references');
      const unfinished = this.unfinishedImport(job);
      if (unfinished) throw unfinished;
    }
    this.db
      .update(importJobs)
      .set({ state, error, updatedAt: new Date().toISOString() })
      .where(eq(importJobs.id, id))
      .run();
  }

  private unfinishedImport(job: {
    id: string;
    sourceId: string;
    isEnumerated: boolean;
  }): UnfinishedImport | null {
    if (!job.isEnumerated) return new UnfinishedImport('enumerate', 'unknown');
    const failures = this.failures(job.id);
    for (const stage of ['download', 'analysis'] as const) {
      const failure = failures.find((item) => item.stage === stage);
      if (failure)
        return new UnfinishedImport(stage, failure.reasonCode ?? 'unknown');
    }
    const isAnalysisMissing = this.references(job.sourceId).some(
      (reference) =>
        !reference.unsupportedReason &&
        (this.observation(reference.id)?.evidence ?? 'provisional') ===
          'provisional',
    );
    return isAnalysisMissing
      ? new UnfinishedImport('analysis', 'unknown')
      : null;
  }

  failures(jobId?: string) {
    return this.db
      .select({ failure: referenceFailures })
      .from(referenceFailures)
      .innerJoin(
        references,
        and(
          eq(references.id, referenceFailures.referenceId),
          eq(references.revision, referenceFailures.revision),
        ),
      )
      .innerJoin(importJobs, eq(importJobs.id, referenceFailures.jobId))
      .innerJoin(
        memberships,
        and(
          eq(memberships.sourceId, importJobs.sourceId),
          eq(memberships.referenceId, references.id),
        ),
      )
      .where(
        and(
          ne(importJobs.state, 'superseded'),
          jobId ? eq(referenceFailures.jobId, jobId) : undefined,
        ),
      )
      .all()
      .map(({ failure }) => failure);
  }

  saveFailure(input: {
    jobId: string;
    referenceId: string;
    revision: number;
    stage: 'download' | 'analysis';
    error: string;
    reasonCode: FailureReasonCode;
  }): void {
    const job = this.jobs().find((item) => item.id === input.jobId);
    const reference =
      job &&
      this.references(job.sourceId).find(
        (item) => item.id === input.referenceId,
      );
    if (!reference || reference.revision !== input.revision)
      throw new Error('Failed reference revision is no longer current');
    if (job?.state !== 'pending') throw new Error('Import job is not pending');
    const values = {
      ...input,
      error: input.error.slice(0, MAX_FAILURE_MESSAGE_LENGTH),
      updatedAt: new Date().toISOString(),
    };
    this.db
      .insert(referenceFailures)
      .values({ ...values, attempts: 1 })
      .onConflictDoUpdate({
        target: [
          referenceFailures.jobId,
          referenceFailures.referenceId,
          referenceFailures.stage,
        ],
        set: { ...values, attempts: sql`${referenceFailures.attempts} + 1` },
      })
      .run();
  }

  clearFailure(referenceId: string, stage: 'download' | 'analysis'): void {
    this.db
      .delete(referenceFailures)
      .where(
        and(
          eq(referenceFailures.referenceId, referenceId),
          eq(referenceFailures.stage, stage),
        ),
      )
      .run();
  }

  saveImportPage(input: ImportPage): void {
    transaction(this.db, () => this.writeImportPage(input));
  }

  approvePlan(input: { id: string; revision: string; isApproved: boolean }) {
    return this.plans.approve({
      ...input,
      createJobs: (plan) => {
        const provider = referenceProvider(plan.profile);
        const jobs = plan.sources.map(
          ({ collection, collectionIds, references: items }) => {
            const remoteId = referenceSourceId({
              profile: plan.profile,
              collection,
            });
            const existing = this.sources().find(
              (source) =>
                source.provider === provider && source.remoteId === remoteId,
            );
            if (existing) assertExplicitSourceSync(existing.syncMode);
            const source = this.addSource({
              provider,
              remoteId,
              title: collection.title,
              url: collection.url ?? undefined,
            });
            if (
              existing &&
              this.jobs().some(
                (job) =>
                  job.sourceId === source.id &&
                  job.state !== 'complete' &&
                  job.state !== 'superseded',
              )
            )
              throw new Error(
                'This collection has an unfinished import; finish or remove it before approving another plan',
              );
            this.db
              .update(sources)
              .set({ isIncluded: true })
              .where(eq(sources.id, source.id))
              .run();
            const job = this.writeImport({
              sourceId: source.id,
              runtime: plan.runtime,
            });
            this.writeImportPage({
              jobId: job.id,
              references: items,
              cursor: null,
              isComplete: true,
              total: items.length,
              remoteId: collection.id,
              title: collection.title,
            });
            return {
              id: job.id,
              sourceId: source.id,
              collectionId: collection.id,
              collectionIds,
            };
          },
        );
        this.setEnabled(true);
        return jobs;
      },
    });
  }

  private writeImportPage({
    jobId,
    references: items,
    cursor,
    isComplete,
    total,
    remoteId,
    title,
    collection,
    shouldPruneUnseen = true,
  }: ImportPage): void {
    if (isComplete !== (cursor === null))
      throw new Error('Import page has inconsistent exhaustion metadata');
    const validated = items.map((item) =>
      ProfileReferenceInputSchema.parse(item),
    );
    const job = this.jobs().find((item) => item.id === jobId);
    if (!job || job.state !== 'pending' || job.isEnumerated)
      throw new Error('Import job is not pending');
    const source = this.source(job.sourceId);
    if (
      remoteId &&
      source.resolvedRemoteId &&
      source.resolvedRemoteId !== remoteId
    )
      throw new Error(
        'Provider source identity changed; reconnect the intended source',
      );
    if (
      cursor &&
      this.db
        .select()
        .from(importCursors)
        .where(
          and(eq(importCursors.jobId, jobId), eq(importCursors.cursor, cursor)),
        )
        .get()
    )
      throw new Error('Provider returned a repeated page cursor');
    let addedCount = 0;
    for (const item of validated) {
      const isMember = this.db
        .select()
        .from(memberships)
        .where(
          and(
            eq(memberships.sourceId, job.sourceId),
            eq(memberships.referenceId, identity(item.provider, item.remoteId)),
          ),
        )
        .get();
      if (!isMember) addedCount += 1;
      const reference = this.writeReference(job.sourceId, item, job.id);
      if (collection)
        this.db
          .insert(importCollectionReferences)
          .values({
            jobId,
            collectionId: collection.id,
            referenceId: reference.id,
          })
          .onConflictDoNothing()
          .run();
    }
    if (collection) {
      const covered = this.db
        .select({ value: count() })
        .from(importCollectionReferences)
        .where(
          and(
            eq(importCollectionReferences.jobId, jobId),
            eq(importCollectionReferences.collectionId, collection.id),
          ),
        )
        .get()?.value;
      if (
        covered === undefined ||
        covered > collection.total ||
        (collection.isComplete && covered !== collection.total)
      )
        throw new Error(
          `Collection import coverage mismatch; refresh the source to enumerate again`,
        );
    }
    const enumerated = this.db
      .select({ value: count() })
      .from(memberships)
      .where(
        and(
          eq(memberships.sourceId, job.sourceId),
          eq(memberships.seenJobId, job.id),
        ),
      )
      .get()?.value;
    if (enumerated === undefined)
      throw new Error('Profile import coverage is unavailable');
    const expected = collection ? null : (total ?? job.total);
    if (isComplete && expected !== null && enumerated !== expected)
      throw new Error(
        `Import coverage mismatch: enumerated ${enumerated} of ${expected}; refresh the source to enumerate again`,
      );
    if (cursor) this.db.insert(importCursors).values({ jobId, cursor }).run();
    if (remoteId)
      this.db
        .update(sources)
        .set({ resolvedRemoteId: remoteId, ...(title ? { title } : {}) })
        .where(eq(sources.id, job.sourceId))
        .run();
    let removedCount = 0;
    if (isComplete && shouldPruneUnseen) {
      const unseen = this.db
        .select()
        .from(memberships)
        .where(
          and(
            eq(memberships.sourceId, job.sourceId),
            or(
              isNull(memberships.seenJobId),
              ne(memberships.seenJobId, job.id),
            ),
          ),
        )
        .all();
      unseen.forEach((membership) => {
        this.db
          .delete(memberships)
          .where(
            and(
              eq(memberships.sourceId, job.sourceId),
              eq(memberships.referenceId, membership.referenceId),
            ),
          )
          .run();
        const reference = this.reference(membership.referenceId);
        if (reference) this.queueOrphan(reference);
      });
      removedCount = unseen.length;
    }
    this.db
      .update(importJobs)
      .set({
        cursor,
        enumerated,
        total: collection && isComplete ? enumerated : (total ?? job.total),
        state: 'pending',
        isEnumerated: isComplete,
        addedCount: job.addedCount + addedCount,
        removedCount: job.removedCount + removedCount,
        updatedAt: new Date().toISOString(),
      })
      .where(eq(importJobs.id, job.id))
      .run();
    this.bump();
  }

  close(): void {
    if (!this.isClosed) {
      this.isClosed = true;
      closeDatabase(this.db);
    }
  }

  private bump(): void {
    this.db
      .update(profile)
      .set({ revision: sql`${profile.revision} + 1` })
      .run();
  }

  private queueOrphan(reference: ProfileReference): void {
    const membership = this.db
      .select()
      .from(memberships)
      .where(eq(memberships.referenceId, reference.id))
      .get();
    if (!membership) this.queue(reference, 'delete');
  }

  private queue(
    reference: ProfileReference,
    operation: 'upsert' | 'delete',
  ): void {
    const value = {
      id: randomUUID(),
      referenceId: reference.id,
      revision: reference.revision,
      operation,
      state: 'pending' as const,
    };
    this.db
      .insert(indexWork)
      .values(value)
      .onConflictDoUpdate({ target: indexWork.referenceId, set: value })
      .run();
  }

  private writeReference(
    sourceId: string,
    input: ProfileReferenceInput,
    seenJobId?: string,
  ): ProfileReference {
    this.source(sourceId);
    const body = ProfileReferenceInputSchema.parse(input);
    const id = identity(body.provider, body.remoteId);
    const current = this.db
      .select()
      .from(references)
      .where(eq(references.id, id))
      .get();
    if (
      current &&
      JSON.stringify({ ...current.body, media: [] }) !==
        JSON.stringify({ ...body, media: [] }) &&
      this.db
        .select({ id: importJobs.id })
        .from(memberships)
        .innerJoin(importJobs, eq(importJobs.id, memberships.seenJobId))
        .innerJoin(
          plannedSources,
          eq(plannedSources.sourceId, memberships.sourceId),
        )
        .where(
          and(
            eq(memberships.referenceId, id),
            inArray(importJobs.state, ['pending', 'paused', 'failed']),
          ),
        )
        .get()
    )
      throw new Error(
        'This reference belongs to an unfinished approved import; finish or remove that source before changing its content',
      );
    if (
      !body.media.length &&
      body.remoteImages?.length &&
      JSON.stringify(body.remoteImages) ===
        JSON.stringify(current?.body.remoteImages) &&
      JSON.stringify(body.remoteImageRepresentations) ===
        JSON.stringify(current?.body.remoteImageRepresentations)
    ) {
      body.media = current?.body.media ?? [];
    }
    const contentHash = identity(JSON.stringify(body));
    const isChanged = current?.contentHash !== contentHash;
    const revision = (current?.revision ?? 0) + (isChanged ? 1 : 0);
    if (isChanged) {
      this.db
        .insert(references)
        .values({ id, revision, contentHash, body })
        .onConflictDoUpdate({
          target: references.id,
          set: { revision, contentHash, body },
        })
        .run();
      this.db
        .delete(observations)
        .where(eq(observations.referenceId, id))
        .run();
      if (current) this.queue({ ...body, id, revision }, 'delete');
      this.bump();
    }
    const set = seenJobId ? { seenJobId } : { referenceId: id };
    this.db
      .insert(memberships)
      .values({ sourceId, referenceId: id, seenJobId })
      .onConflictDoUpdate({
        target: [memberships.sourceId, memberships.referenceId],
        set,
      })
      .run();
    const work = this.db
      .select()
      .from(indexWork)
      .where(eq(indexWork.referenceId, id))
      .get();
    const reference = { ...body, id, revision };
    if (!this.observation(id)) this.writeProvisionalObservation(reference);
    else if (!isChanged && (!work || work.operation === 'delete'))
      this.queue(reference, 'upsert');
    return reference;
  }

  private writeProvisionalObservation(reference: ProfileReference): void {
    const body = ProfileObservationSchema.parse({
      referenceId: reference.id,
      revision: reference.revision,
      description: provisionalDescription(reference),
      runtime: 'user',
      evidence: 'provisional',
    });
    this.db
      .insert(observations)
      .values({ referenceId: reference.id, revision: reference.revision, body })
      .onConflictDoUpdate({
        target: observations.referenceId,
        set: { revision: reference.revision, body },
      })
      .run();
    this.queue(reference, 'upsert');
    this.bump();
  }
}
